  Lemma swrap32_errsum' : ltac2:(CDefT.buildp (gd_tbl_A_x509_get_ext_A ()) "Pr,$5.Pc,$5.P,(6.(23.-10000.R2.)(24.R2.=))P,(6.(24.(33.(30.+2.+40.)+10000.)R2.)(23.R2.(30.+2.+40.)))(7.$5.(40.&20.(1<.(32.R4.+10000000000000000.)R3.))(1<.R4.(33.R3.(30.+2.+40.))))")
